/* From Uiverse.io by Yaya12085 - Tags: form, active, input, comment */
.__UIV_SCOPE__ .card {
  background-color: #fff;
  border-radius: 10px;
  padding: 20px;
  width: 350px;
  display: flex;
  flex-direction: column;
}

.__UIV_SCOPE__ .title {
  font-size: 24px;
  font-weight: 600;
  text-align: center;
}

.__UIV_SCOPE__ .form {
  margin-top: 20px;
  display: flex;
  flex-direction: column;
}

.__UIV_SCOPE__ .group {
  position: relative;
}

.__UIV_SCOPE__ .form .group label {
  font-size: 14px;
  color: rgb(99, 102, 102);
  position: absolute;
  top: -10px;
  left: 10px;
  background-color: #fff;
  transition: all .3s ease;
}

.__UIV_SCOPE__ .form .group input,
.__UIV_SCOPE__ .form .group textarea {
  padding: 10px;
  border-radius: 5px;
  border: 1px solid rgba(0, 0, 0, 0.2);
  margin-bottom: 20px;
  outline: 0;
  width: 100%;
  background-color: transparent;
}

.__UIV_SCOPE__ .form .group input:placeholder-shown+ label, .__UIV_SCOPE__ .form .group textarea:placeholder-shown +label {
  top: 10px;
  background-color: transparent;
}

.__UIV_SCOPE__ .form .group input:focus,
.__UIV_SCOPE__ .form .group textarea:focus {
  border-color: #3366cc;
}

.__UIV_SCOPE__ .form .group input:focus+ label, .__UIV_SCOPE__ .form .group textarea:focus +label {
  top: -10px;
  left: 10px;
  background-color: #fff;
  color: #3366cc;
  font-weight: 600;
  font-size: 14px;
}

.__UIV_SCOPE__ .form .group textarea {
  resize: none;
  height: 100px;
}

.__UIV_SCOPE__ .form button {
  background-color: #3366cc;
  color: #fff;
  border: none;
  border-radius: 5px;
  padding: 10px;
  font-size: 16px;
  cursor: pointer;
  transition: all 0.3s ease;
}

.__UIV_SCOPE__ .form button:hover {
  background-color: #27408b;
}
